function main(inputs) {
  var scores = inputs.scores;
  if (!Array.isArray(scores)) {
    throw new Error("scores 必须是数字数组");
  }
  var counts = { A: 0, B: 0, C: 0, D: 0 };
  for (var i = 0; i < scores.length; i++) {
    var s = Number(scores[i]);
    if (s >= 90) {
      counts.A += 1;
    } else if (s >= 75) {
      counts.B += 1;
    } else if (s >= 60) {
      counts.C += 1;
    } else {
      counts.D += 1;
    }
  }
  return { a: counts.A, b: counts.B, c: counts.C, d: counts.D };
}
